def _dependency_solver(name_order, preference):
    def solve(data):
        packages = data["packages"]
        names = sorted(packages, reverse=(name_order == "descending"))
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        options = []
        for name in names:
            rows = [row for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
            options.append([None] + rows)

        best_vector = None
        best_versions = None
        for choices in product(*options):
            selected = {name: row for name, row in zip(names, choices)
                        if row is not None}
            edges = {name: [] for name in selected}
            valid = True
            for name, bounds in data["roots"].items():
                row = selected.get(name)
                if row is None or not bounds[0] <= row["version"] <= bounds[1]:
                    valid = False
                    break
            if not valid:
                continue
            for name, row in selected.items():
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    target = selected.get(dep["name"])
                    if (target is None or
                            not dep["min"] <= target["version"] <= dep["max"]):
                        valid = False
                        break
                    edges[name].append(dep["name"])
                if not valid:
                    break
            if not valid:
                continue

            reached = set()
            stack = list(data["roots"])
            while stack:
                name = stack.pop()
                if name in reached:
                    continue
                reached.add(name)
                stack.extend(edges[name])
            if reached != set(selected):
                continue

            finished, active = set(), set()
            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges[name]:
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            if not all(visit(name) for name in selected):
                continue
            vector = tuple(selected[name]["version"] if name in selected else -1
                           for name in names)
            better = (best_vector is None or
                      (vector < best_vector if preference == "minimum"
                       else vector > best_vector))
            if better:
                best_vector = vector
                best_versions = {name: row["version"]
                                 for name, row in selected.items()}
        if best_versions is None:
            return {"error": "unsatisfiable"}
        return {"versions": best_versions}
    return solve


def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (2 * numerator + denominator) // (2 * denominator)
    return numerator // denominator


def _ledger(data):
    cutoff = data.get("cutoff", 10**9)
    winners = {}
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        key = (sequence, event.get("revision", 0), position)
        if event_id not in winners or key > winners[event_id][0]:
            winners[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    for _, event in winners.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, data["rounding"])
        tax = _round(raw * event.get("tax_bp", 0), 10000, data["rounding"])
        amount = net + tax
        if event.get("kind") == "refund":
            amount = -amount
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + amount
    return {"balances": balances}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    available = [job for job in jobs if job["id"] not in blocked]
    if not mandatory.issubset({job["id"] for job in available}):
        return {"error": "impossible"}
    best_value = None
    best_ids = None
    for chosen in combinations(available, k):
        ids = tuple(sorted(job["id"] for job in chosen))
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in chosen:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in data.get("quotas", {}).items()):
            continue
        ordered = sorted(chosen, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in chosen)
        if (best_value is None or value > best_value or
                (value == best_value and ids > best_ids)):
            best_value, best_ids = value, ids
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    required_bit = {node: 1 << i for i, node in enumerate(required)}
    full_mask = (1 << len(required)) - 1
    initial_mask = required_bit.get(data["source"], 0)
    start_state = (data["source"], initial_mask, data["coupons"])
    distances = {start_state: data["start"]}
    queue = [(data["start"],) + start_state]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full_mask and remaining == 0:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            durations = [(edge["duration"], remaining)]
            if remaining:
                durations.append((max(1, edge["duration"] - edge.get("discount", 0)),
                                  remaining - 1))
            for duration, next_remaining in durations:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | required_bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_remaining)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival,) + next_state)
    return {"arrival": None}


